import { AsyncLocalStorage } from 'node:async_hooks';

export type RequestAuthContextValue = {
  token?: string;
  refreshToken?: string;
  mcpAccessToken?: string;
  email?: string;
  userId?: string;
};

const requestAuthStorage = new AsyncLocalStorage<RequestAuthContextValue>();

export const runWithRequestAuthContext = <T>(
  value: RequestAuthContextValue,
  callback: () => T,
): T => {
  return requestAuthStorage.run(value, callback);
};

export const updateRequestAuthContext = (
  value: Partial<RequestAuthContextValue>,
): void => {
  const current = requestAuthStorage.getStore();
  if (!current) {
    return;
  }
  Object.assign(current, value);
};

export const getRequestAuthContext = (): RequestAuthContextValue | null => {
  return requestAuthStorage.getStore() ?? null;
};
